mapper.select:
select t.column_type_define_id, t.database_type, t.column_type_classify, t.column_type_name, t.column_standard_size, t.remark, t.type_category, t.max_precision, t.max_scale, t.character_max_length, t.min_value, t.max_value, t.is_national_flag, t.require_length_param from data_stream_column_type_define t
order by t.column_type_define_id
${sqlLimit}

select count(1)
from data_stream_column_type_define
where database_type = #{databaseType}
  and column_type_name = #{columnTypeName}

    and column_type_define_id <> #{excludeId}

select count(1)
from data_stream_column_type_map
where column_type_define_id_a = #{columnTypeDefineId}
   or column_type_define_id_b = #{columnTypeDefineId}

select a.column_type_map_id, a.column_type_define_id_a, b.database_type database_type_a, b.column_type_name column_type_name_a, a.column_type_define_id_b, c.database_type database_type_b, c.column_type_name column_type_name_b, a.match_level, a.precision_conversion_rule, a.length_conversion_rule, a.conversion_warning, a.is_reversible from data_stream_column_type_map a, data_stream_column_type_define b, data_stream_column_type_define c where a.column_type_define_id_a = b.column_type_define_id and a.column_type_define_id_b = c.column_type_define_id
and b.database_type = #{queryValue}
and c.database_type = #{queryValue}
order by a.column_type_map_id
${sqlLimit}

select count(1)
from data_stream_column_type_map a,
     data_stream_column_type_define b,
     data_stream_column_type_define c
where a.column_type_define_id_a = b.column_type_define_id
  and a.column_type_define_id_b = c.column_type_define_id

    and b.database_type = #{queryValue}


    and c.database_type = #{queryValue}
